# Week 6's deflations landed late in the week, so everyone owing makeup from
# them has it moved to week 7, the same as if they'd chosen that themselves.
MOVED_WEEK = 6
THRESHOLD_MINUTES = 60


def move_week_6_makeup(apps, schema_editor):
    """A MakeupDeferral for every user whose week 6 cuts are owed as makeup.

    The same rows challenge._makeup_rows counts, over the same threshold, so
    exactly the people with makeup due in week 6 get it moved. Anyone who's
    cut later in week 6 gets the usual choice on their dashboard.
    """
    if weeks.week_count() <= MOVED_WEEK:
        return
    TimelapseRemoval = apps.get_model("atlantis_site", "TimelapseRemoval")
    MakeupDeferral = apps.get_model("atlantis_site", "MakeupDeferral")
    opens, closes = weeks.week_bounds(MOVED_WEEK)

    seconds = {}
    for owner, removed in TimelapseRemoval.objects.filter(
        counts_toward_makeup=True,
        session__journal__isnull=False,
        session__journal__project__deleted=False,
        created_at__gte=opens,
        created_at__lt=closes,
    ).values_list("session__owner", F("end_seconds") - F("start_seconds")):
        seconds[owner] = seconds.get(owner, 0) + (removed or 0)

    MakeupDeferral.objects.bulk_create(
        [
            MakeupDeferral(user_id=owner, week_index=MOVED_WEEK)
            for owner, total in seconds.items()
            if total // 60 > THRESHOLD_MINUTES
        ],
        ignore_conflicts=True,
    )


